('aria-label="Mein Profil">?</button>','aria-label="My profile">?</button>'),
('<h1 id="hello">Lerne den Quran lesen – Buchstabe für Buchstabe</h1>','<h1 id="hello">Learn to read the Quran – letter by letter</h1>'),
('<p>Ich bin Qalam, deine Schreibfeder. Zusammen gehen wir durch sechs Welten: Buchstaben, Formen, kurze Vokale, Sukun, schwere & leichte Buchstaben und die Zahlen. Für jede Lektion bekommst du bis zu drei Sterne.</p>','<p>I\'m Qalam, your reed pen. Together we travel through six worlds: letters, forms, short vowels, sukun, heavy & light letters and numbers. For every lesson you get up to three stars.</p>'),
('id="cta">Weiterlernen</button>','id="cta">Keep learning</button>'),
('<p class="foot">Tipp: Lies jede Silbe laut. Die richtige Aussprache lernst du am besten mit deinem Lehrer oder deiner Lehrerin.</p>','<p class="foot">Tip: read every syllable out loud. Correct pronunciation is best learnt with your teacher.</p>'),
('aria-label="Lektion beenden"','aria-label="End lesson"'),
('role="progressbar" aria-label="Fortschritt"','role="progressbar" aria-label="Progress"'),
('<p>Wie heißt du? Dann weiß Qalam, mit wem er lernt.</p>','<p>What\'s your name? Then Qalam knows who he is learning with.</p>'),
('placeholder="Dein Vorname"','placeholder="Your first name"'),
('id="nameGo">Los geht\'s</button>','id="nameGo">Let\'s go</button>'),
# letters
('["ا","Alif","ā","Alif verlängert ein „a“. Trägt es eine Hamza (أ), ist es ein kurzer Stopp wie in „be-achten“.",0,"kein Punkt"]','["ا","Alif","ā","Alif lengthens an “a”. When it carries a hamza (أ), it is a short stop, like the break in “uh-oh”.",0,"no dot"]'),
('["ب","Ba","b","Wie das deutsche „b“.",0,"1 Punkt unten"]','["ب","Ba","b","Like the English “b”.",0,"1 dot below"]'),
('["ت","Ta","t","Wie das deutsche „t“.",0,"2 Punkte oben"]','["ت","Ta","t","Like the English “t”.",0,"2 dots above"]'),
('["ث","Tha","th","Wie „th“ im englischen „think“ – die Zunge kommt kurz zwischen die Zähne.",0,"3 Punkte oben"]','["ث","Tha","th","Like “th” in “think” – the tongue comes briefly between the teeth.",0,"3 dots above"]'),
('["ج","Dschim","dsch","Wie „dsch“ in „Dschungel“.",0,"1 Punkt in der Mitte"]','["ج","Jim","j","Like “j” in “jungle”.",0,"1 dot in the middle"]'),
('["ح","Ḥa","ḥ","Ein gehauchtes „h“ aus der Mitte des Halses – wie wenn du eine Brille anhauchst.",0,"kein Punkt"]','["ح","Ḥa","ḥ","A breathy “h” from the middle of the throat – like when you breathe on glasses to clean them.",0,"no dot"]'),
('["خ","Kha","kh","Wie „ch“ in „Bach“.",1,"1 Punkt oben"]','["خ","Kha","kh","Like “ch” in the Scottish “loch”.",1,"1 dot above"]'),
('["د","Dal","d","Wie das deutsche „d“.",0,"kein Punkt"]','["د","Dal","d","Like the English “d”.",0,"no dot"]'),
('["ذ","Dhal","dh","Wie „th“ im englischen „this“.",0,"1 Punkt oben"]','["ذ","Dhal","dh","Like “th” in “this”.",0,"1 dot above"]'),
('["ر","Ra","r","Ein gerolltes „r“ mit der Zungenspitze.",0,"kein Punkt"]','["ر","Ra","r","A rolled “r” made with the tip of the tongue.",0,"no dot"]'),
('["ز","Zay","z","Ein summendes „s“ wie in „Sonne“.",0,"1 Punkt oben"]','["ز","Zay","z","Like the English “z” in “zoo”.",0,"1 dot above"]'),
('["س","Sin","s","Ein scharfes „s“ wie in „Fuß“.",0,"kein Punkt"]','["س","Sin","s","A sharp “s” like in “sun”.",0,"no dot"]'),
('["ش","Schin","sch","Wie „sch“ in „Schule“.",0,"3 Punkte oben"]','["ش","Shin","sh","Like “sh” in “ship”.",0,"3 dots above"]'),
('["ص","Ṣad","ṣ","Ein schweres, dunkles „s“.",1,"kein Punkt"]','["ص","Ṣad","ṣ","A heavy, dark “s”.",1,"no dot"]'),
('["ض","Ḍad","ḍ","Ein schweres „d“, gesprochen mit dem Rand der Zunge.",1,"1 Punkt oben"]','["ض","Ḍad","ḍ","A heavy “d”, spoken with the side of the tongue.",1,"1 dot above"]'),
('["ط","Ṭa","ṭ","Ein schweres, dunkles „t“.",1,"kein Punkt"]','["ط","Ṭa","ṭ","A heavy, dark “t”.",1,"no dot"]'),
('["ظ","Ẓa","ẓ","Ein schweres „th“ wie in „this“.",1,"1 Punkt oben"]','["ظ","Ẓa","ẓ","A heavy “th” as in “this”.",1,"1 dot above"]'),
('["ع","ʿAin","ʿ","Kommt gepresst aus der Mitte des Halses.",0,"kein Punkt"]','["ع","ʿAin","ʿ","Comes squeezed from the middle of the throat.",0,"no dot"]'),
('["غ","Ghain","gh","Wie ein gegurgeltes Rachen-„r“.",1,"1 Punkt oben"]','["غ","Ghain","gh","Like a gargled “r” from the back of the throat, as in French “Paris”.",1,"1 dot above"]'),
('["ف","Fa","f","Wie das deutsche „f“.",0,"1 Punkt oben"]','["ف","Fa","f","Like the English “f”.",0,"1 dot above"]'),
('["ق","Qaf","q","Ein „k“ ganz hinten im Hals.",1,"2 Punkte oben"]','["ق","Qaf","q","A “k” made right at the back of the throat.",1,"2 dots above"]'),
('["ك","Kaf","k","Wie das deutsche „k“.",0,"kein Punkt"]','["ك","Kaf","k","Like the English “k”.",0,"no dot"]'),
('["ل","Lam","l","Wie das deutsche „l“.",0,"kein Punkt"]','["ل","Lam","l","Like the English “l”.",0,"no dot"]'),
('["م","Mim","m","Wie das deutsche „m“.",0,"kein Punkt"]','["م","Mim","m","Like the English “m”.",0,"no dot"]'),
('["ن","Nun","n","Wie das deutsche „n“.",0,"1 Punkt oben"]','["ن","Nun","n","Like the English “n”.",0,"1 dot above"]'),
('["ه","Ha","h","Wie das „h“ in „Haus“.",0,"kein Punkt"]','["ه","Ha","h","Like the “h” in “house”.",0,"no dot"]'),
('["و","Waw","w","Wie das englische „w“ in „water“.",0,"kein Punkt"]','["و","Waw","w","Like the “w” in “water”.",0,"no dot"]'),
('["ي","Ya","y","Wie das deutsche „j“ in „ja“.",0,"2 Punkte unten"]','["ي","Ya","y","Like the “y” in “yes”.",0,"2 dots below"]'),
('const POSNAME={start:"am Anfang",mid:"in der Mitte",end:"am Ende"};','const POSNAME={start:"at the beginning",mid:"in the middle",end:"at the end"};'),
('a:{m:"َ",n:"Fatha",pos:"über"},i:{m:"ِ",n:"Kasra",pos:"unter"},u:{m:"ُ",n:"Dhamma",pos:"über"}','a:{m:"َ",n:"Fatha",pos:"above"},i:{m:"ِ",n:"Kasra",pos:"below"},u:{m:"ُ",n:"Dhamma",pos:"above"}'),
# generators
('mcq({ask:["Welcher Buchstabe ist ",{q:x.name},"?"]},x.c,others(x.c,3),"ar",`${x.c} heißt ${x.name} (${x.dots}).`)','mcq({ask:["Which letter is ",{q:x.name},"?"]},x.c,others(x.c,3),"ar",`${x.c} is called ${x.name} (${x.dots}).`)'),
('mcq({big:x.c,ask:["Wie heißt dieser Buchstabe?"]},x.name,others(x.c,3).map(c=>byC[c].name),"tx",`Das ist ${x.name}.`)','mcq({big:x.c,ask:["What is this letter called?"]},x.name,others(x.c,3).map(c=>byC[c].name),"tx",`This is ${x.name}.`)'),
('mcq({ask:["Finde ",{q:x.name},"!"],sub:"Schau genau auf die Punkte."}','mcq({ask:["Find ",{q:x.name},"!"],sub:"Look carefully at the dots."}'),
('mcq({big:f,ask:["Welcher Buchstabe ist das?"],sub:"So sieht er "+POSNAME[pos]+" eines Wortes aus."},x.c,others(x.c,3),"ar",`${f} ist ${x.name} (${x.c}) ${POSNAME[pos]}.`)','mcq({big:f,ask:["Which letter is this?"],sub:"This is how it looks "+POSNAME[pos]+" of a word."},x.c,others(x.c,3),"ar",`${f} is ${x.name} (${x.c}) ${POSNAME[pos]}.`)'),
('mcq({ask:["Welcher Buchstabe verbindet sich ",{q:"nicht"}," mit dem nächsten?"]},nc,w,"ar",`${byC[nc].name} (${nc}) gehört zu den 6, die nicht nach links verbinden: ا د ذ ر ز و.`)','mcq({ask:["Which letter does ",{q:"not"}," join to the next one?"]},nc,w,"ar",`${byC[nc].name} (${nc}) is one of the 6 that don\'t join to the left: ا د ذ ر ز و.`)'),
('mcq({big:syl(x.c,v),ask:["Wie liest du das?"]},sylT(x.c,v),w,"tx",`${syl(x.c,v)} = ${sylT(x.c,v)} – ${V[v].n} ${V[v].pos} dem Buchstaben macht ein kurzes „${v}“.`)','mcq({big:syl(x.c,v),ask:["How do you read this?"]},sylT(x.c,v),w,"tx",`${syl(x.c,v)} = ${sylT(x.c,v)} – ${V[v].n} ${V[v].pos} the letter makes a short “${v}”.`)'),
('mcq({big:syl(x.c,v),ask:["Fatha, Kasra oder Dhamma?"],sub:"Schau, wo das Zeichen steht."},sylT(x.c,v),w,"tx",`${V[v].n} ${V[v].pos} dem Buchstaben = „${v}“. Also: ${sylT(x.c,v)}.`)','mcq({big:syl(x.c,v),ask:["Fatha, Kasra or Dhamma?"],sub:"Look where the mark is."},sylT(x.c,v),w,"tx",`${V[v].n} ${V[v].pos} the letter = “${v}”. So: ${sylT(x.c,v)}.`)'),
('mcq({big:w,ask:["Wie liest du dieses Wort?"],sub:"Der kleine Kreis ist ein Sukun."},t,wr,"tx",`${w} = ${t}. Den Buchstaben mit Sukun liest du ohne Vokal.`)','mcq({big:w,ask:["How do you read this word?"],sub:"The small circle is a sukun."},t,wr,"tx",`${w} = ${t}. You read the letter with sukun without a vowel.`)'),
('{type:"intro",title:"Jeder Buchstabe hat 4 Formen",text:"Im Wort verbinden sich die Buchstaben. Je nachdem, ob ein Buchstabe allein, am Anfang, in der Mitte oder am Ende steht, sieht er etwas anders aus. Gelesen wird er aber immer gleich.",big:"بـ ـبـ ـب"}','{type:"intro",title:"Every letter has 4 forms",text:"In a word the letters join together. Depending on whether a letter stands alone, at the beginning, in the middle or at the end, it looks a little different. But it is always read the same way.",big:"بـ ـبـ ـب"}'),
('{type:"intro",title:"Die 6, die nicht verbinden",text:"Diese Buchstaben verbinden sich nur mit dem Buchstaben davor, nie mit dem danach. Nach ihnen beginnt der nächste Buchstabe neu.",big:"ا د ذ ر ز و"}','{type:"intro",title:"The 6 that don\'t join",text:"These letters only join to the letter before them, never to the one after. After them, the next letter starts afresh.",big:"ا د ذ ر ز و"}'),
('a:{title:"Fatha – das kurze „a“",text:"Die Fatha ist ein kleiner schräger Strich über dem Buchstaben. Sie macht ein kurzes „a“. Bei den schweren (blauen) Buchstaben klingt das „a“ etwas dunkler.",ex:"بَ",exT:"ba"}','a:{title:"Fatha – the short “a”",text:"The fatha is a small slanted stroke above the letter. It makes a short “a”. With the heavy (blue) letters the “a” sounds a little darker.",ex:"بَ",exT:"ba"}'),
('i:{title:"Kasra – das kurze „i“",text:"Die Kasra ist ein kleiner schräger Strich unter dem Buchstaben. Sie macht ein kurzes „i“. Merke: Kasra – unten – „i“.",ex:"بِ",exT:"bi"}','i:{title:"Kasra – the short “i”",text:"The kasra is a small slanted stroke below the letter. It makes a short “i”. Remember: kasra – below – “i”.",ex:"بِ",exT:"bi"}'),
('u:{title:"Dhamma – das kurze „u“",text:"Die Dhamma sieht aus wie ein kleines Waw (و) über dem Buchstaben. Sie macht ein kurzes „u“, dabei werden die Lippen rund.",ex:"بُ",exT:"bu"}','u:{title:"Dhamma – the short “u”",text:"The dhamma looks like a small waw (و) above the letter. It makes a short “u”, and the lips become round.",ex:"بُ",exT:"bu"}'),
('{type:"tafel",title:"Lies die Tafel",text:"Lies jede Silbe laut. Tippe darauf, um zu prüfen, ob du richtig liegst.",','{type:"tafel",title:"Read the board",text:"Read every syllable out loud. Tap it to check whether you were right.",'),
('{type:"intro",title:"Sukun – kein Vokal",text:"Der kleine Kreis über einem Buchstaben heißt Sukun. Er bedeutet: hier kommt kein Vokal. Den Buchstaben liest du direkt zusammen mit dem Buchstaben davor.",big:"مِنْ",bigT:"min"}','{type:"intro",title:"Sukun – no vowel",text:"The small circle above a letter is called sukun. It means: no vowel here. You read the letter straight together with the letter before it.",big:"مِنْ",bigT:"min"}'),
('{type:"intro",title:"Qalqala – das Echo",text:"Fünf Buchstaben „springen“, wenn sie ein Sukun haben: ق ط ب ج د. Du sprichst sie mit einem kleinen Echo. Merksatz: قُطْبُ جَدٍّ.",big:"قَدْ",bigT:"qad"}','{type:"intro",title:"Qalqala – the echo",text:"Five letters “bounce” when they have a sukun: ق ط ب ج د. You say them with a small echo. To remember them: قُطْبُ جَدٍّ.",big:"قَدْ",bigT:"qad"}'),
('{type:"tafel",title:"Lies die Wörter",text:"Lies jedes Wort laut. Tippe darauf, um zu prüfen.",','{type:"tafel",title:"Read the words",text:"Read every word out loud. Tap it to check.",'),
('const RA=[["رَبٌّ","schwer","Ra mit Fatha"],["رُسُلٌ","schwer","Ra mit Dhamma"],["رِزْقٌ","leicht","Ra mit Kasra"],["رِجَالٌ","leicht","Ra mit Kasra"],["مَرْيَمُ","schwer","Ra mit Sukun nach Fatha"],["قُرْآنٌ","schwer","Ra mit Sukun nach Dhamma"],["فِرْعَوْنُ","leicht","Ra mit Sukun nach Kasra"],["يَرْجِعُ","schwer","Ra mit Sukun nach Fatha"],["رُوحٌ","schwer","Ra mit Dhamma"],["رِيحٌ","leicht","Ra mit Kasra"]];','const RA=[["رَبٌّ","heavy","Ra with fatha"],["رُسُلٌ","heavy","Ra with dhamma"],["رِزْقٌ","light","Ra with kasra"],["رِجَالٌ","light","Ra with kasra"],["مَرْيَمُ","heavy","Ra with sukun after fatha"],["قُرْآنٌ","heavy","Ra with sukun after dhamma"],["فِرْعَوْنُ","light","Ra with sukun after kasra"],["يَرْجِعُ","heavy","Ra with sukun after fatha"],["رُوحٌ","heavy","Ra with dhamma"],["رِيحٌ","light","Ra with kasra"]];'),
('const ALLAH=[["قَالَ ٱللَّهُ","schwer","vor Allah steht eine Fatha"],["نَصْرُ ٱللَّهِ","schwer","vor Allah steht eine Dhamma"],["رَسُولَ ٱللَّهِ","schwer","vor Allah steht eine Fatha"],["عَبْدُ ٱللَّهِ","schwer","vor Allah steht eine Dhamma"],["بِسْمِ ٱللَّهِ","leicht","vor Allah steht eine Kasra"],["لِلَّهِ","leicht","vor dem Lam steht eine Kasra"],["بِٱللَّهِ","leicht","vor Allah steht eine Kasra"]];','const ALLAH=[["قَالَ ٱللَّهُ","heavy","there is a fatha before Allah"],["نَصْرُ ٱللَّهِ","heavy","there is a dhamma before Allah"],["رَسُولَ ٱللَّهِ","heavy","there is a fatha before Allah"],["عَبْدُ ٱللَّهِ","heavy","there is a dhamma before Allah"],["بِسْمِ ٱللَّهِ","light","there is a kasra before Allah"],["لِلَّهِ","light","there is a kasra before the Lam"],["بِٱللَّهِ","light","there is a kasra before Allah"]];'),
('const HL=["schwer","leicht"];','const HL=["heavy","light"];'),
('{big:x.c,ask:["Schwer oder leicht?"]},opts:HL.map(v=>({v,ok:(v==="schwer")===hv})),kind:"tx",explain:hv?`${x.name} gehört zu den 7 schweren Buchstaben: خ ص ض غ ط ق ظ.`:`${x.name} ist ein leichter Buchstabe – er klingt hell.`','{big:x.c,ask:["Heavy or light?"]},opts:HL.map(v=>({v,ok:(v==="heavy")===hv})),kind:"tx",explain:hv?`${x.name} is one of the 7 heavy letters: خ ص ض غ ط ق ظ.`:`${x.name} is a light letter – it sounds bright.`'),
('{big:syl(c,v),ask:["Klingt diese Silbe ",{q:"dunkel"}," oder ",{q:"hell"},"?"]},opts:HL.map(w=>({v:w,ok:(w==="schwer")===isH})),kind:"tx",explain:isH?`${byC[c].name} ist schwer – der Mund wird voll, der Laut klingt dunkel.`:`${byC[c].name} ist leicht – sein Partner ${byC[hv].name} wäre schwer.`','{big:syl(c,v),ask:["Does this syllable sound ",{q:"dark"}," or ",{q:"bright"},"?"]},opts:HL.map(w=>({v:w,ok:(w==="heavy")===isH})),kind:"tx",explain:isH?`${byC[c].name} is heavy – the mouth becomes full and the sound is dark.`:`${byC[c].name} is light – its partner ${byC[hv].name} would be heavy.`'),
('{big:w,ask:["Ist das ",{q:"Ra"}," schwer oder leicht?"]}','{big:w,ask:["Is the ",{q:"Ra"}," heavy or light?"]}'),
('{big:w,ask:["Ist das ",{q:"Lam"}," in „Allah“ schwer oder leicht?"]},opts:HL.map(v=>({v,ok:v===a})),kind:"tx",explain:`${why[0].toUpperCase()+why.slice(1)} → das Lam ist ${a}.`','{big:w,ask:["Is the ",{q:"Lam"}," in “Allah” heavy or light?"]},opts:HL.map(v=>({v,ok:v===a})),kind:"tx",explain:`${why[0].toUpperCase()+why.slice(1)} → the Lam is ${a}.`'),
('{type:"intro",title:"Helle und dunkle Buchstaben",text:"Manche Buchstaben klingen dunkel und voll – das sind die schweren Buchstaben. Dabei hebt sich der hintere Teil der Zunge zum Gaumen, der Mund wird „voll“. Alle anderen klingen hell und dünn – das sind die leichten Buchstaben. Im Buch sind die schweren Buchstaben blau.",big:"ص  س",bigT:"schwer · leicht"}','{type:"intro",title:"Bright and dark letters",text:"Some letters sound dark and full – these are the heavy letters. The back of the tongue rises towards the palate and the mouth becomes “full”. All the others sound bright and thin – these are the light letters. In the book the heavy letters are blue.",big:"ص  س",bigT:"heavy · light"}'),
('{type:"intro",title:"Die 7 schweren Buchstaben",text:"Diese sieben sind immer schwer, egal welcher Vokal darauf steht. Merksatz zum Lernen: خُصَّ ضَغْطٍ قِظْ",big:"خ ص ض غ ط ق ظ",heavy:1}','{type:"intro",title:"The 7 heavy letters",text:"These seven are always heavy, whatever vowel they carry. A phrase to remember them: خُصَّ ضَغْطٍ قِظْ",big:"خ ص ض غ ط ق ظ",heavy:1}'),
('{type:"intro",title:"Tipp: Alif nach schweren Buchstaben",text:"Kommt nach einem schweren Buchstaben ein Alif (langes a), wird auch das Alif dunkel gelesen. Nach einem leichten Buchstaben bleibt es hell.",big:"طَا  تَا",bigT:"ṭā (dunkel) · tā (hell)"}','{type:"intro",title:"Tip: Alif after heavy letters",text:"When an Alif (long a) comes after a heavy letter, the Alif is read dark too. After a light letter it stays bright.",big:"طَا  تَا",bigT:"ṭā (dark) · tā (bright)"}'),
('{type:"intro",title:"Ra – mal schwer, mal leicht",text:"Ra ist schwer, wenn es eine Fatha oder Dhamma hat. Ra ist leicht, wenn es eine Kasra hat. Hat Ra ein Sukun, schau auf den Buchstaben davor: Fatha oder Dhamma davor → schwer, Kasra davor → leicht.",big:"رَ  رُ  رِ",bigT:"schwer · schwer · leicht"}','{type:"intro",title:"Ra – sometimes heavy, sometimes light",text:"Ra is heavy when it has a fatha or dhamma. Ra is light when it has a kasra. If Ra has a sukun, look at the letter before it: fatha or dhamma before → heavy, kasra before → light.",big:"رَ  رُ  رِ",bigT:"heavy · heavy · light"}'),
('{type:"tafel",title:"Lies die Ra-Wörter",text:"Tippe auf ein Wort, um zu sehen, ob das Ra schwer oder leicht ist.",','{type:"tafel",title:"Read the Ra words",text:"Tap a word to see whether the Ra is heavy or light.",'),
('{type:"intro",title:"Das Lam im Namen Allahs",text:"Steht vor dem Namen Allah eine Fatha oder Dhamma, wird das Lam schwer und voll gesprochen. Steht davor eine Kasra, bleibt es leicht.",big:"قَالَ ٱللَّهُ",bigT:"schwer – Fatha davor"}','{type:"intro",title:"The Lam in the name of Allah",text:"If there is a fatha or dhamma before the name Allah, the Lam is said heavy and full. If there is a kasra before it, it stays light.",big:"قَالَ ٱللَّهُ",bigT:"heavy – fatha before"}'),
('{type:"intro",title:"Leicht nach Kasra",text:"Bei „Bismillah“ steht vor Allah eine Kasra – deshalb ist das Lam hier leicht.",big:"بِسْمِ ٱللَّهِ",bigT:"leicht – Kasra davor"}','{type:"intro",title:"Light after kasra",text:"In “Bismillah” there is a kasra before Allah – that is why the Lam is light here.",big:"بِسْمِ ٱللَّهِ",bigT:"light – kasra before"}'),
('{big:AD[n],ask:["Welche Zahl ist das?"]}','{big:AD[n],ask:["Which number is this?"]}'),
('explain:`${AD[n]} ist die ${n}.`+(n===5?" Achtung: Die 5 sieht aus wie ein kleiner Kreis!":n===0?" Die 0 ist nur ein kleiner Punkt.":"")','explain:`${AD[n]} is ${n}.`+(n===5?" Careful: the 5 looks like a small circle!":n===0?" The 0 is just a small dot.":"")'),
('{ask:["Finde die ",{q:String(n)},"!"]}','{ask:["Find the ",{q:String(n)},"!"]}'),
('explain:`Die ${n} schreibt man ${AD[n]}.`','explain:`${n} is written ${AD[n]}.`'),
('{big:arNum(n),ask:["Wie heißt diese Zahl?"],sub:"Arabische Zahlen liest man von links nach rechts – wie bei uns!"}','{big:arNum(n),ask:["What is this number?"],sub:"Arabic numbers are read from left to right – just like ours!"}'),
('{type:"intro",title:"Die arabischen Zahlen",text:"Im Quran stehen die Seiten- und Ayah-Nummern in diesen Zahlen. Die Wörter liest man von rechts nach links – die Zahlen aber von links nach rechts, genau wie bei uns.",big:"١٢٣",bigT:"123"}','{type:"intro",title:"The Arabic numbers",text:"In the Quran the page and ayah numbers are written with these numbers. Words are read from right to left – but numbers from left to right, just like ours.",big:"١٢٣",bigT:"123"}'),
('{type:"tafel",title:"Die Zahlen von 0 bis 9",text:"Tippe auf eine Zahl, um zu sehen, welche es ist.",','{type:"tafel",title:"The numbers 0 to 9",text:"Tap a number to see which one it is.",'),
('{type:"intro",title:"Vorsicht, Verwechslungsgefahr!",text:"Die arabische ٥ ist eine 5 – auch wenn sie wie eine 0 aussieht. Die Null ist nur ein kleiner Punkt: ٠. Und ٦ ist die 6, nicht die 7!",big:"٥  ٠  ٦",bigT:"5 · 0 · 6"}','{type:"intro",title:"Careful, easy to mix up!",text:"The Arabic ٥ is a 5 – even though it looks like a 0. Zero is just a small dot: ٠. And ٦ is 6, not 7!",big:"٥  ٠  ٦",bigT:"5 · 0 · 6"}'),
