# makharij
('t:"Aus dem leeren Raum von Mund und Hals – die Luft fließt einfach heraus."','t:"From the empty space of the mouth and throat – the air simply flows out."'),
('t:"Ganz tief unten im Hals, nahe der Brust."','t:"Deep down in the throat, near the chest."'),
('t:"Aus der Mitte des Halses."','t:"From the middle of the throat."'),
('t:"Aus dem oberen Teil des Halses, nahe beim Mund."','t:"From the upper part of the throat, close to the mouth."'),
('t:"Hinterster Teil der Zunge drückt an den weichen Gaumen."','t:"The very back of the tongue presses against the soft palate."'),
('t:"Hintere Zunge am Gaumen – etwas weiter vorne als beim Qaf."','t:"The back of the tongue against the palate – a little further forward than for Qaf."'),
('t:"Die Mitte der Zunge hebt sich zum harten Gaumen."','t:"The middle of the tongue rises to the hard palate."'),
('t:"Der Rand der Zunge drückt an die oberen Backenzähne."','t:"The side of the tongue presses against the upper back teeth."'),
('t:"Der vordere Zungenrand berührt das Zahnfleisch oben."','t:"The front edge of the tongue touches the upper gum."'),
('t:"Die Zungenspitze am Zahnfleisch oben – der Ton klingt durch die Nase."','t:"The tip of the tongue at the upper gum – the sound goes through the nose."'),
('t:"Die Zungenspitze, etwas weiter hinten als beim Nun – sie rollt leicht."','t:"The tip of the tongue, a little further back than for Nun – it rolls slightly."'),
('t:"Die Zungenspitze tippt an die Wurzeln der oberen Schneidezähne."','t:"The tip of the tongue taps the roots of the upper front teeth."'),
('t:"Die Zungenspitze kommt kurz zwischen die Zähne."','t:"The tip of the tongue comes briefly between the teeth."'),
('t:"Die Zungenspitze liegt hinter den unteren Zähnen – es zischt."','t:"The tip of the tongue lies behind the lower teeth – it hisses."'),
('t:"Die Unterlippe berührt die oberen Schneidezähne."','t:"The lower lip touches the upper front teeth."'),
('t:"Beide Lippen arbeiten zusammen."','t:"Both lips work together."'),
('const MKEXTRA={"و":" Die Lippen werden dabei rund.","م":" Der Ton klingt dabei auch durch die Nase.","ب":" Die Lippen gehen fest zu und springen auf."};','const MKEXTRA={"و":" The lips become round.","م":" The sound also goes through the nose.","ب":" The lips close firmly and spring open."};'),
